class Ticket {
  static sold = 0;

  static sell() {
    this.sold += 1;
  }
}

class VipTicket extends Ticket {}
class GroupTicket extends Ticket {}

Ticket.sell();
VipTicket.sell();
VipTicket.sell();
Ticket.sell();

console.log(Ticket.sold);
console.log(VipTicket.sold);
console.log(GroupTicket.sold);
console.log(Object.hasOwn(GroupTicket, "sold"));
